// Security encyclopedia content. Every article is hand-authored reference
// material — no data here comes from a live provider, so nothing is dated
// or attributed to a source that could go stale silently. References cite
// public standards (RFCs, CWE/CVE/CVSS, MITRE ATT&CK, OWASP) by identifier
// only, not by URL, since this module never fetches anything.

export type ArticleCategory = "web" | "network" | "malware" | "identity" | "cloud" | "detection" | "crypto";

export const CATEGORY_LABEL: Record<ArticleCategory, string> = {
  web: "Web & application",
  network: "Network",
  malware: "Malware",
  identity: "Identity & access",
  cloud: "Cloud & infrastructure",
  detection: "Detection & response",
  crypto: "Cryptography",
};

export interface Reference {
  label: string;
  note?: string;
}

export interface Article {
  slug: string;
  title: string;
  category: ArticleCategory;
  summary: string;
  what: string;
  why: string;
  how: string;
  detection: string;
  defence: string;
  related: string[];
  references: Reference[];
}

