export function getArticle(slug: string): Article | undefined {
  return ARTICLES.find((a) => a.slug === slug);
}

export function relatedArticles(a: Article): Article[] {
  return a.related.map((slug) => getArticle(slug)).filter((x): x is Article => !!x);
}

export function searchArticles(query: string, category?: ArticleCategory): Article[] {
  const q = query.trim().toLowerCase();
  return ARTICLES.filter((a) => {
    if (category && a.category !== category) return false;
    if (!q) return true;
    return a.title.toLowerCase().includes(q) || a.summary.toLowerCase().includes(q) || a.what.toLowerCase().includes(q);
  });
}
